import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, texture as textureNode } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();
  root.name = 'cta-label';

  const ownedGeometries = [];
  const ownedMaterials = [];
  const timelines = [];
  let loadedTexture = null;
  let cleaned = false;

  const createGradientMaterial = (topColor, bottomColor) => {
    const material = new MeshBasicNodeMaterial();
    const localUv = uv();
    const gradient = smoothstep(0.0, 1.0, localUv.y);
    material.colorNode = mix(
      vec4(bottomColor[0], bottomColor[1], bottomColor[2], 1.0),
      vec4(topColor[0], topColor[1], topColor[2], 1.0),
      gradient
    );
    material.toneMapped = false;
    ownedMaterials.push(material);
    return material;
  };

  const backdropGeometry = new PlaneGeometry(7.0, 6.0);
  ownedGeometries.push(backdropGeometry);

  const backdropMaterial = createGradientMaterial(
    [0.086275, 0.086275, 0.113725],
    [0.043137, 0.043137, 0.062745]
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  const buttonGeometry = new PlaneGeometry(3.25, 0.86);
  ownedGeometries.push(buttonGeometry);

  const buttonMaterial = createGradientMaterial(
    [0.086275, 0.086275, 0.113725],
    [0.023529, 0.023529, 0.039216]
  );

  const button = new Mesh(buttonGeometry, buttonMaterial);
  button.name = 'machined-metal-cta-surface';
  button.position.set(0, 0, 0);
  root.add(button);

  const accentGeometry = new PlaneGeometry(3.25, 0.045);
  ownedGeometries.push(accentGeometry);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38',
    toneMapped: false
  });
  ownedMaterials.push(accentMaterial);

  const accentBar = new Mesh(accentGeometry, accentMaterial);
  accentBar.name = 'signal-red-machined-edge';
  accentBar.position.set(0, -0.407, 0.035);
  root.add(accentBar);

  const innerAccentGeometry = new PlaneGeometry(0.22, 0.045);
  ownedGeometries.push(innerAccentGeometry);

  const innerAccent = new Mesh(innerAccentGeometry, accentMaterial);
  innerAccent.name = 'signal-red-foreground-detail';
  innerAccent.position.set(-1.515, 0.407, 0.04);
  root.add(innerAccent);

  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  textGroup.name = 'cta-copy';

  let textOffset = 0;
  for (const item of textItems) {
    const content = typeof item.text === 'string' ? item.text : '';
    if (!content) continue;

    const textObject = ctx.fontAtlas.createText(content, {
      fontSize: item.typography?.fontSize ?? 42,
      color: '#e8ecf2',
      align: 'center',
      maxWidthPx: 720,
      letterSpacingPx: item.typography?.letterSpacingPx
    });

    textObject.position.set(0, textOffset, 0.065);
    textGroup.add(textObject);
    textOffset -= 0.18;
  }

  root.add(textGroup);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (cleaned) {
        tex.dispose?.();
        return;
      }

      loadedTexture = tex;
      const metalTexture = textureNode(tex, uv());
      const localUv = uv();
      const gradient = smoothstep(0.0, 1.0, localUv.y);
      const baseSurface = mix(
        vec4(0.043137, 0.043137, 0.062745, 1.0),
        vec4(0.086275, 0.086275, 0.113725, 1.0),
        gradient
      );

      buttonMaterial.colorNode = mix(baseSurface, metalTexture, 0.28);
      buttonMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const entrance = gsap.timeline();
  entrance.fromTo(
    root.scale,
    { x: 0.985, y: 0.985, z: 0.985 },
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.42, ease: 'power3.out' }
  ).to(
    root.scale,
    { x: 1, y: 1, z: 1, duration: 0.48, ease: 'power4.out' }
  );
  timelines.push(entrance);

  root.userData.handlers = {};
  root.userData.cleanup = () => {
    if (cleaned) return;
    cleaned = true;

    for (const timeline of timelines) {
      timeline.kill();
    }

    for (const geometry of ownedGeometries) {
      geometry.dispose?.();
    }

    for (const material of ownedMaterials) {
      material.dispose?.();
    }

    loadedTexture?.dispose?.();
    root.clear();
  };

  return root;
}
